INSERT INTO muscle_info
    (muscle_name, overview, anatomy, muscle_function, example_exercises, synergist_muscles, recovery_window)
VALUES
('Chest', 'The chest musculature forms the anterior powerhouse of the upper torso, playing a foundational role in all horizontal and diagonal pressing mechanics.', 'Composed primarily of the pectoralis major (spanning clavicular and sternocostal heads) and the underlying pectoralis minor, originating along the sternum and clavicle.', 'Responsible for horizontal adduction, flexion, and internal rotation of the humerus at the glenohumeral joint.', 'Barbell Bench Press, Incline Dumbbell Press, Cable Crossovers', 'Front Deltoids, Triceps Brachii', '48–72 Hours'),
('Shoulders', 'The deltoids create the foundational width of the upper body, providing 360-degree mobility and stability to the glenohumeral joint.', 'Comprised of three distinct heads: the anterior (front), lateral (side), and posterior (rear) deltoids, which surround the shoulder joint.', 'Facilitates arm abduction, flexion, extension, and rotation. Crucial for all overhead pressing and pulling movements.', 'Overhead Barbell Press, Lateral Raises, Reverse Pec Deck', 'Trapezius, Triceps Brachii', '48 Hours'),
('Lats', 'The latissimus dorsi is the broadest muscle of the back, essential for V-taper aesthetics and vertical pulling power.', 'A massive fan-shaped muscle originating from the lower spine and iliac crest, inserting into the humerus.', 'Primarily responsible for shoulder extension, adduction, and internal rotation (pulling the arms down and back).', 'Pull-Ups, Lat Pulldowns, Barbell Rows', 'Biceps Brachii, Rear Deltoids, Trapezius', '48–72 Hours'),
('Trapezius', 'A diamond-shaped muscle group dominating the upper back and neck, vital for scapular health and heavy lifting stability.', 'Spans from the base of the skull down to the lower thoracic vertebrae and outward to the scapula. Divided into upper, middle, and lower regions.', 'Elevates, retracts, and depresses the scapula. Essential for stabilizing the shoulder girdle during deadlifts and rows.', 'Barbell Shrugs, Face Pulls, Farmer Walks', 'Rhomboids, Rear Deltoids', '48 Hours'),
('Biceps', 'The primary elbow flexors on the anterior upper arm, heavily recruited in all pulling movements.', 'Consists of two heads (short and long) originating from the scapula and inserting into the radius of the forearm.', 'Responsible for elbow flexion (curling) and forearm supination (turning the palm upward).', 'Barbell Curls, Incline Dumbbell Curls, Hammer Curls', 'Brachialis, Forearm Flexors', '48 Hours'),
('Triceps', 'The triceps make up roughly two-thirds of the upper arm mass, providing the lock-out power for all pressing exercises.', 'A three-headed muscle (lateral, long, and medial) located on the posterior of the upper arm, inserting at the elbow (olecranon).', 'The primary extensor of the elbow joint. The long head also assists in shoulder extension.', 'Close-Grip Bench Press, Skull Crushers, Tricep Pushdowns', 'Chest, Front Deltoids', '48 Hours'),
('Forearms', 'A complex group of smaller muscles responsible for grip strength, wrist mobility, and stabilizing heavy loads.', 'Composed of numerous anterior flexors and posterior extensors spanning from the elbow down to the carpals and phalanges.', 'Controls wrist flexion, extension, pronation, supination, and the gripping action of the fingers.', 'Wrist Curls, Reverse Curls, Deadlift Holds', 'Biceps Brachii, Brachialis', '24–48 Hours'),
('Core', 'The central pillar of the body, transferring force between the lower and upper body while protecting the spine.', 'Includes the rectus abdominis (six-pack), transversus abdominis (deep core), and erector spinae (lower back).', 'Provides spinal flexion, anti-extension, anti-rotation, and intra-abdominal pressure for heavy compound lifts.', 'Planks, Hanging Leg Raises, Ab Wheel Rollouts', 'Obliques, Hip Flexors', '24–48 Hours'),
('Obliques', 'The muscles flanking the abdomen, crucial for rotational power and lateral stability.', 'Consists of the external and internal obliques running diagonally along the lateral sides of the torso.', 'Responsible for torso rotation, lateral flexion (side bending), and resisting unwanted rotational forces.', 'Russian Twists, Cable Woodchoppers, Side Planks', 'Core (Rectus Abdominis), Serratus Anterior', '24–48 Hours'),
('Quads', 'The massive muscle group on the front of the thigh, driving lower body pushing power and jumping mechanics.', 'Composed of four distinct muscles: rectus femoris, vastus lateralis, vastus medialis, and vastus intermedius.', 'The primary extensors of the knee. The rectus femoris also assists in hip flexion.', 'Barbell Squats, Leg Press, Bulgarian Split Squats', 'Glutes, Calves', '48–72 Hours'),
('Hams', 'The hamstrings sit on the posterior thigh, balancing the quads and providing explosive hip extension.', 'A three-muscle group (biceps femoris, semitendinosus, semimembranosus) originating at the ischial tuberosity and inserting below the knee.', 'Responsible for knee flexion (curling the leg) and hip extension (driving the hips forward).', 'Romanian Deadlifts (RDLs), Lying Leg Curls, Glute-Ham Raises', 'Glutes, Erector Spinae', '48–72 Hours'),
('Glutes', 'The largest and most powerful muscle group in the human body, essential for locomotion, posture, and athletic power.', 'Comprised of the gluteus maximus (main bulk), gluteus medius (upper/side), and gluteus minimus.', 'Drives hip extension, external rotation, and abduction. Stabilizes the pelvis during single-leg movements.', 'Barbell Hip Thrusts, Sumo Deadlifts, Walking Lunges', 'Hamstrings, Quads, Core', '48–72 Hours'),
('Calves', 'The dense musculature of the lower leg, dictating ankle mobility and explosive ground reaction forces.', 'Primarily made up of the gastrocnemius (the visible diamond shape) and the underlying soleus.', 'Responsible for plantar flexion (pointing the toes). The gastrocnemius also slightly assists in knee flexion.', 'Standing Calf Raises, Seated Calf Raises, Jump Rope', 'Hamstrings, Achilles Tendon', '24–48 Hours');
